import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        int m = Integer.parseInt(inputLine[1]);

        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }

        Map<Integer, Integer> factor(int num) {
            Map<Integer, Integer> factorsMap = new HashMap<>();
            for (int p : primes) {
                if (p * p > num) {
                    break;
                }
                if (num % p == 0) {
                    int count = 0;
                    while (num % p == 0) {
                        num /= p;
                        count++;
                    }
                    factorsMap.put(p, count);
                }
            }
            if (num > 1) {
                factorsMap.put(num, 1);
            }
            return factorsMap;
        }

        List<Long> getFactors(int num) {
            Map<Integer, Integer> primeFactors = factor(num);
            List<Long> result = new ArrayList<>();
            result.add(1L);
            for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
                int p = entry.getKey();
                int count = entry.getValue();
                List<Long> newList = new ArrayList<>();
                for (Long val : result) {
                    for (int i = 0; i <= count; i++) {
                        newList.add(val * pow(p, i));
                    }
                }
                result = newList;
            }
            return result;
        }

        long compute(int n, int m) {
            Map<Integer, Long> f = new HashMap<>();
            f.put(0, 0L);
            f.put(1, 1L);
            f.put(2, 2L);
            for (int i = 3; i <= n; i++) {
                long val = 2 * f.get(i - 1);
                for (long x : getFactors(i)) {
                    if (2 <= x && x <= i) {
                        long term1 = f.getOrDefault((int)(i / x), 0L);
                        long term2 = f.getOrDefault((int)((i - 1) / x), 0L);
                        val += term1 - term2;
                        val %= m;
                    }
                }
                val %= m;
                f.put(i, val);
            }
            return f.get(n);
        }

        System.out.println(compute(n, m));
    }

    static long pow(int base, int exp) {
        long result = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result *= b;
            }
            b *= b;
            exp >>= 1;
        }
        return result;
    }
}
